3	import (
4		"testing"
5		"time"
6	)
7	
8	func TestChartResultVersionsAreIndependent(t *testing.T) {
9		dir := t.TempDir()
10		s, err := Open(dir)
11		if err != nil {
12			t.Fatal(err)
13		}
14		defer s.Close()
15		actor := InternalActor("dr-1")
16	
17		p, err := s.RegisterPatient(actor, "Alice")
18		if err != nil {
19			t.Fatal(err)
20		}
21		enc, err := s.AddEncounter(actor, p.ID, time.Now())
22		if err != nil {
23			t.Fatal(err)
24		}
25		rec, err := s.CreateDraft(actor, p.ID, enc.ID, Diagnosis, "initial dx")
