11	// 本文件为内部查询 EncounterRecords 的“返回结果隔离”约定补回归保障：
12	// 内部使用者通过它查看某次就诊时，拿到的草稿与完整历史只是本次查询的独立
13	// 结果。调用方在手中的结果上整理内容，既不能改掉正式病历，也不能改掉另一
14	// 份先前取得的查询结果；诊断与医嘱一视同仁。
15	//
16	// 预期基线由测试自行深拷贝（刻意不调用生产代码的任何拷贝逻辑）：即便生产
17	// 侧 buildHistory 退化为浅拷贝，基线仍保持查询时内容，隔离断言才能真正
18	// 抓住底层数组或版本指针的泄漏。
19	
20	// ---- 测试自用的独立深拷贝（不经过生产代码） ----
21	
22	// snapshotHistory 独立深拷贝一条就诊记录视图作为预期基线。
23	func snapshotHistory(h RecordHistory) RecordHistory {
24		cp := h
25		cp.Record.Versions = append([]ID(nil), h.Record.Versions...)
26		vs := make([]Version, len(h.Versions))
27		copy(vs, h.Versions)
28		cp.Versions = vs
29		if h.CurrentVersion != nil {
30			cv := *h.CurrentVersion
31			cp.CurrentVersion = &cv
32		}
33		return cp
34	}
35	
36	// snapshotHistories 独立深拷贝整份就诊查询结果。
37	func snapshotHistories(hs []RecordHistory) []RecordHistory {
38		out := make([]RecordHistory, len(hs))
39		for i, h := range hs {
40			out[i] = snapshotHistory(h)
41		}
42		return out
43	}
44	
45	func historiesByID(hs []RecordHistory) map[ID]RecordHistory {
46		m := make(map[ID]RecordHistory, len(hs))
47		for _, h := range hs {
48			m[h.Record.ID] = h
49		}
50		return m
51	}
52	
53	// tamperHistory 在调用方手中的一条结果上做尽可能广泛的本地修改：
54	// 记录标识与就诊归属、版本标识列表（就地改写）、草稿内容与草稿标记、
55	// 当前版本视图的全部字段，以及历史版本的内容/原因/上一版本关系并整体逆序。
56	func tamperHistory(h *RecordHistory) {
57		h.Record.ID = "rec_local_tampered"
58		h.Record.PatientID = "pat_local_tampered"
59		h.Record.EncounterID = "enc_local_tampered"
60		// 就地改写版本标识列表：与正式历史或另一份结果共享底层数组时会污染对方。
61		for i := range h.Record.Versions {
62			h.Record.Versions[i] = ID(fmt.Sprintf("ver_local_tampered_%d", i))
63		}
64		h.Record.DraftContent = "调用方本地篡改的草稿内容"
65		h.HasDraft = !h.HasDraft // 翻转草稿标记
66	
67		if h.CurrentVersion != nil {
68			h.CurrentVersion.ID = "ver_cv_local_tampered"
69			h.CurrentVersion.RecordID = "rec_local_tampered"
70			h.CurrentVersion.Number = 999
71			h.CurrentVersion.Content = "调用方本地篡改的当前版本内容"
72			h.CurrentVersion.PrevID = "ver_cv_local_prev"
73			h.CurrentVersion.Reason = "调用方本地伪造的更正原因"
74		}
75	
76		if len(h.Versions) > 0 {
77			h.Versions[0].ID = "ver_hist_local_tampered"
78			h.Versions[0].Content = "调用方本地篡改的历史内容"
79			h.Versions[0].Reason = "调用方本地伪造的历史原因"
80			h.Versions[0].PrevID = "ver_hist_local_prev"
81			// 就地逆序：共享底层数组时会改掉另一份结果的版本顺序。
82			for i, j := 0, len(h.Versions)-1; i < j; i, j = i+1, j-1 {
83				h.Versions[i], h.Versions[j] = h.Versions[j], h.Versions[i]
84			}
85		}
86	}
87	
88	func assertHistoryMatches(t *testing.T, got, want RecordHistory, label string) {
89		t.Helper()
90		gr, wr := got.Record, want.Record
91		if gr.ID != wr.ID || gr.PatientID != wr.PatientID || gr.EncounterID != wr.EncounterID ||
92			gr.Category != wr.Category || gr.DraftContent != wr.DraftContent || gr.HasDraft != wr.HasDraft ||
93			gr.CurrentVersionID != wr.CurrentVersionID {
94			t.Fatalf("%s: record header changed:\n got=%+v\nwant=%+v", label, gr, wr)
95		}
96		if !reflect.DeepEqual(gr.Versions, wr.Versions) {
97			t.Fatalf("%s: official version id list changed:\n got=%v\nwant=%v", label, gr.Versions, wr.Versions)
98		}
99		if (got.CurrentVersion == nil) != (want.CurrentVersion == nil) {
100			t.Fatalf("%s: current version presence changed: got present=%v, want present=%v",
101				label, got.CurrentVersion != nil, want.CurrentVersion != nil)
102		}
103		if want.CurrentVersion != nil && *got.CurrentVersion != *want.CurrentVersion {
104			t.Fatalf("%s: current version changed:\n got=%+v\nwant=%+v",
105				label, *got.CurrentVersion, *want.CurrentVersion)
106		}
107		if len(got.Versions) != len(want.Versions) {
108			t.Fatalf("%s: history length changed: got %d versions, want %d versions\ngot=%+v",
109				label, len(got.Versions), len(want.Versions), got.Versions)
110		}
111		for i := range want.Versions {
112			if got.Versions[i] != want.Versions[i] {
113				t.Fatalf("%s: history version %d changed:\n got=%+v\nwant=%+v",
114					label, i, got.Versions[i], want.Versions[i])
115			}
116		}
117	}
118	
119	// assertHistoriesMatches 按位置逐元素比对（两种视图都按记录标识稳定排序）。
120	func assertHistoriesMatches(t *testing.T, got, want []RecordHistory, label string) {
121		t.Helper()
122		if len(got) != len(want) {
123			t.Fatalf("%s: record count changed: got %d (%v), want %d (%v)",
124				label, len(got), recordIDList(got), len(want), recordIDList(want))
125		}
126		for i := range want {
127			assertHistoryMatches(t, got[i], want[i], fmt.Sprintf("%s [%d]", label, i))
128		}
129	}
