282			cd.Versions[1].Reason != "诊断更正原因" {
283			t.Fatalf("corrected diagnosis chain wrong: %+v", cd.Versions)
284		}
285		do2 := m2[draftOrd]
286		if do2.CurrentVersion != nil || !do2.HasDraft || do2.DraftContent != "草稿医嘱内容" {
287			t.Fatalf("draft order shape wrong: %+v", do2)
288		}
289	}
