291	// ---- 隔离：在手中的结果上整理内容，改不到正式病历，也改不到另一份结果 ----
292	
293	func TestEncounterRecordsResultIsDetachedFromStore(t *testing.T) {
294		s, _ := newTestStore(t)
295		pid, e1 := setupPatientEncounter(t, s)
296		e2, err := s.AddEncounter(doc, pid, time.Date(2026, 3, 1, 0, 0, 0, 0, time.UTC))
