1	package clinical
2	
3	import (
4		"fmt"
5		"time"
6	)
7	
8	// RegisterPatient 登记一名合成患者并返回其稳定标识。
9	// 只有内部使用者可以登记患者。
10	func (s *Store) RegisterPatient(actor Actor, name string) (Patient, error) {
11		if !actor.valid() || !actor.IsInternal() {
12			return Patient{}, ErrAccessDenied
13		}
14		if name == "" {
15			return Patient{}, fmt.Errorf("%w: patient name is required", ErrInvalidArgument)
16		}
17	
18		var result Patient
19		err := s.mutate(func(snap *snapshot) error {
20			now := s.now()
21			p := &Patient{
22				ID:        newID("pat"),
23				Name:      name,
24				Source:    SyntheticSource,
25				CreatedAt: now,
26			}
27			snap.Patients[p.ID] = p
28			result = *p
29			return nil
30		})
31		return result, err
32	}
33	
34	// AddEncounter 在患者档案下登记一次就诊。患者必须存在且未停用。
35	// occurredAt 为零值时取当前时间。
36	func (s *Store) AddEncounter(actor Actor, patientID ID, occurredAt time.Time) (Encounter, error) {
37		if !actor.valid() || !actor.IsInternal() {
38			return Encounter{}, ErrAccessDenied
39		}
40		if patientID == "" {
41			return Encounter{}, fmt.Errorf("%w: patient id is required", ErrInvalidArgument)
42		}
43	
44		var result Encounter
45		err := s.mutate(func(snap *snapshot) error {
46			p, err := requireActivePatient(snap, patientID)
47			if err != nil {
48				return err
49			}
50			at := occurredAt
51			if at.IsZero() {
52				at = s.now()
53			}
54			e := &Encounter{
55				ID:         newID("enc"),
56				PatientID:  p.ID,
57				OccurredAt: at.UTC(),
58				CreatedAt:  s.now(),
59			}
60			snap.Encounters[e.ID] = e
61			result = *e
62			return nil
63		})
64		return result, err
65	}
66	
67	// DeactivatePatient 停用患者档案。停用后不能新增就诊、改动草稿、使记录生效、
68	// 进行更正或新建授权，接收方也无法继续读取；内部使用者仍可查看全部历史。
69	//
70	// 重复停用返回成功且不产生额外变化（不新增审计事件）。
71	func (s *Store) DeactivatePatient(actor Actor, patientID ID) error {
72		if !actor.valid() || !actor.IsInternal() {
73			return ErrAccessDenied
74		}
75		return s.mutate(func(snap *snapshot) error {
76			p, err := requirePatient(snap, patientID)
77			if err != nil {
78				return err
79			}
80			if p.Deactivated {
81				// 幂等：正式保存的患者状态已经是停用。确认已有结果即可——保持首次
82				// 停用的时间与操作身份，不生成额外变化或事件，也不落盘：重复确认不
83				// 依赖当前能否写入本地数据，任何内部使用者的合法确认都得到同一结果，
84				// 且不能把首次停用改成确认者的信息。一次保存失败的停用尝试不会改变
85				// 正式状态，因此不会被当作成功依据。
86				return errUnchanged
87			}
