50	// 命中已保存交换的重试只是读取既有结果、不产生任何状态变更，因此不再落盘：
51	// 即使本地保存条件当前不可用，重试也成功返回正式保存的那份交换。
52	func (s *Store) CreateExchange(actor Actor, patientID ID, receiverID, authorizationID ID, recordIDs []ID, requestID string) (Exchange, error) {
53		if !actor.valid() || !actor.IsInternal() {
54			return Exchange{}, ErrAccessDenied
