			t.Fatalf("actor %+v denied chart leaked content: %+v", actor, got)
		}
	}

	// 被拒查询不改变审计。
	if got := len(mustAudit(t, s, d.pa)); got != 8 {
		t.Fatalf("denied chart queries changed A audit count: %d", got)
	}
}

